// Generated by scripts/sync-core.mjs from Nexora-Saas src/lib/workforce/task-extras.test.ts. Do not edit: change the web repository and run npm run sync:core.
import { describe, expect, it } from "vitest"
import { findByKey, isOnTask, isWebUrl, nextTaskNumber, parseInline, parseRichText, taskKey, taskLinks, taskPeople } from "./task-extras"
import { buildInbox } from "./inbox"
import { Priority, TaskRelationType, TaskStatus, type WorkProject, type WorkTask } from "../../types/work-projects"

const task = (id: string, over: Partial<WorkTask> = {}): WorkTask =>
  ({ id, workspaceId: "ws", projectId: "p1", title: id, status: TaskStatus.TODO, priority: Priority.MEDIUM, estimatedHours: 1, subtasks: [], order: 0, createdAt: "", updatedAt: "", ...over }) as WorkTask
const projects = [{ id: "p1", code: "ORB-01" }, { id: "p2", code: "HEL-02" }] as WorkProject[]

describe("richer tasks (P1)", () => {
  it("builds keys and numbers per project", () => {
    expect(taskKey({ number: 4 }, { code: "ORB-01" })).toBe("ORB-01#4")
    expect(taskKey({}, { code: "ORB-01" })).toBe("")
    const tasks = [task("a", { number: 3 }), task("b", { number: 7, projectId: "p2" }), task("c")]
    expect(nextTaskNumber(tasks, "p1")).toBe(4)
    expect(nextTaskNumber(tasks, "p3")).toBe(1)
  })

  it("lists the main person first and counts collaborators as on the task", () => {
    const t = task("a", { assigneeId: "lina", collaboratorIds: ["omar", "lina", "julia"] })
    expect(taskPeople(t)).toEqual(["lina", "omar", "julia"])
    expect(isOnTask(t, "julia")).toBe(true)
    expect(isOnTask(t, "karim")).toBe(false)
    expect(taskPeople(task("b"))).toEqual([])
  })

  it("reads links between tasks from both sides", () => {
    const a = task("a", { dependsOn: ["b"], relations: [{ type: TaskRelationType.RELATES, taskId: "c" }] })
    const b = task("b")
    const c = task("c", { relations: [{ type: TaskRelationType.DUPLICATE, taskId: "a" }] })
    const all = [a, b, c]
    expect(taskLinks(a, all)).toMatchObject({ blockedBy: [b], blocks: [], duplicates: [c], relates: [c] })
    expect(taskLinks(b, all).blocks).toEqual([a])
    expect(taskLinks(c, all)).toMatchObject({ duplicates: [a], relates: [a] })
  })

  it("finds a task from its key, ignoring case", () => {
    const tasks = [task("a", { number: 4 }), task("b", { number: 4, projectId: "p2" })]
    expect(findByKey("orb-01#4", tasks, projects)?.id).toBe("a")
    expect(findByKey("HEL-02#4", tasks, projects)?.id).toBe("b")
    expect(findByKey("ORB-01#9", tasks, projects)).toBeUndefined()
    expect(findByKey("nope", tasks, projects)).toBeUndefined()
  })

  it("accepts web links only", () => {
    expect(isWebUrl("https://figma.com/file/1")).toBe(true)
    expect(isWebUrl("javascript:alert(1)")).toBe(false)
    expect(isWebUrl("ftp://x.y")).toBe(false)
  })

  it("parses light formatting without reading HTML", () => {
    expect(parseInline("**Bold** and _it_ with `x`, see [doc](https://a.b/c) or ORB-01#4 <b>no</b>")).toEqual([
      { kind: "bold", text: "Bold" },
      { kind: "text", text: " and " },
      { kind: "italic", text: "it" },
      { kind: "text", text: " with " },
      { kind: "code", text: "x" },
      { kind: "text", text: ", see " },
      { kind: "link", text: "doc", url: "https://a.b/c" },
      { kind: "text", text: " or " },
      { kind: "key", text: "ORB-01#4" },
      { kind: "text", text: " <b>no</b>" },
    ])
    expect(parseInline("snake_case_name stays")).toEqual([{ kind: "text", text: "snake_case_name stays" }])
    expect(parseInline("[x](javascript:alert(1))").every((p) => p.kind === "text")).toBe(true)
  })

  it("splits a description into blocks", () => {
    const blocks = parseRichText("# Goal\nShip it\nsoon\n\n- one\n- two\n1. first\n- [x] done\n- [ ] todo")
    expect(blocks.map((b) => b.kind)).toEqual(["heading", "paragraph", "bullets", "numbers", "checks"])
    expect(blocks[1]).toEqual({ kind: "paragraph", inlines: [{ kind: "text", text: "Ship it soon" }] })
    expect(blocks[2]).toMatchObject({ items: [[{ text: "one" }], [{ text: "two" }]] })
    expect(blocks[4]).toMatchObject({ items: [{ done: true }, { done: false }] })
  })

  it("rings the bell for late tasks a person watches but does not work on", () => {
    const base = { rights: { approveTime: false, invoices: false, hr: false }, employees: [], reviews: [], entries: [], leave: [], expenses: [], invoices: [], documents: [], today: "2026-10-20" }
    const tasks = [
      task("late", { title: "Late one", dueDate: "2026-10-10", watcherIds: ["sara"] }),
      task("soon", { dueDate: "2026-10-30", watcherIds: ["sara"] }),
      task("done", { dueDate: "2026-10-10", status: TaskStatus.DONE, watcherIds: ["sara"] }),
      task("mine", { dueDate: "2026-10-10", collaboratorIds: ["sara"], watcherIds: ["sara"] }),
    ]
    const items = buildInbox({ ...base, viewer: { employeeId: "sara", isAdmin: false }, tasks })
    expect(items.find((i) => i.title === "inboxWatched")).toMatchObject({ values: { count: 1, task: "Late one" }, href: "/dashboard/projects/p1?task=late" })
    expect(items.find((i) => i.title === "inboxTasks")?.values.count).toBe(1)
  })
})
